INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (141, 1, 7, 'BirdDog P100 Basic Streaming Kit w/ RS422 Remote PTZ Control', 'birddog-p100-basic-streaming-kit-w-rs422-remote-ptz-control', 'The BirdDog P100 Basic Streaming Kit w/ RS422 Remote PTZ Control is a one-click, end-to-PC, PTZ camera control and streaming solution that is both Windows and Mac compatible and requires no IP or advanced networking experience to get started. Perfect for capturing and streaming virtual events, our kit is centered around the popular BirdDog P100 PTZ camera and includes all the accessories and cables you’ll need to start streaming from a compatible computer while allowing you the freedom to choose your own tripod.

The BirdDog P100 Basic Streaming Kit w/ RS422 Remote PTZ Control includes:

BirdDog Eyes P100 NDI PTZ Camera
	BirdDog IR Remote
	BirdDog PTZ Keyboard
	Elgato Game Capture HD60 S
	Belden 150ft Cat 6A Ethernet Cable
	 Monoprice 50ft Luxe Series Active HDMI Male-Male Cable

Sachtler Ace M Fluid Head with 2-Stage Aluminum Tripod
	Sachtler Ace XL Fluid Head Tripod System
	Manfrotto 502HD Fluid Head w/ 475B Pro Tripod
	MeFOTO GlobeTrotter Carbon Fiber Travel Tripod Kit

Extension Cord 25ft
	Masterplug 100-foot Extension Reel 4-Outlet
	Accell PowerSquid Flexible 5-Outlet Surge Protector
	APC SurgeArrest 8-Outlet Surge Protector

Westcott Solix Bi-Color 3-Light Compact Kit
