INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (189, 1, 8, 'Blackmagic Design URSA Cine Immersive Camera', 'blackmagic-design-ursa-cine-immersive-camera', 'Enter the realm of 180° media with the URSA Cine Immersive Camera from Blackmagic Design. The innovative cinema camera boasts Apple Immersive Video support with dual 8160 × 7200 58.7MP sensors capable of capturing immersive 8K images at up to 90 fps and with a whopping 16 stops of dynamic range. The camera is equipped with a wide range of connectivity options, including 12G-SDI, 10G Ethernet, USB-C, and XLR for high-end professional audio capture. It records Blackmagic RAW files and has a convenient fold-out 5" touchscreen monitor with HDR support.

