INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (193, 1, 8, 'Blackmagic Design URSA Mini Pro 12K OLPF (PL)', 'blackmagic-design-ursa-mini-pro-12k-olpf-pl', 'The Blackmagic Design URSA Mini Pro 12K OLPF (PL) is a PL-mount compatible, 12K cinema camera capable of RAW capture and adds an OLPF to the URSA Mini Pro 12K. Key features include:

User-changeable PL lens mount
Dual CFast 2.0 or SD card recording
4K Super16 up to 220 fps
