INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (292, 1, 12, 'Canon 5DS R', 'canon-5ds-r', 'The Canon 5DS R is a professional-grade, ultra high-resolution DSLR. Key features include:

50.6MP full-frame sensor
61-point high-density reticular AF
Full HD 1080p capture at 30 fps in ALL-I and IPB
