INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (566, 2, 14, 'DJI Action 6 FOV Boost Lens', 'dji-action-6-fov-boost-lens', 'The FOV Boost Lens is a lens adapter that is compatible with the DJI Osmo Action 6 and widens the field of view from 155º to 182°. It is splash resistant but not waterproof, so it is not meant for underwater use. To use it, you must unscrew the lens cover on the Action 6 and replace it with this lens adapter. Distortion Control will still work when using this lens.', 550000.0, '{"Brand": "DJI", "Item Type": "Lens", "Lens Mount": "Add-on", "Lens Type": "Wide Angle", "Stabilization": "No", "Weather Sealing": "No", "Zoom Type": "Fixed Focal Length"}', 'Includes

