INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (580, 2, 14, 'DJI Wide-Angle Lens for Osmo Pocket 3', 'dji-wide-angle-lens-for-osmo-pocket-3', 'This DJI Wide-Angle Lens attaches to the lens of your Osmo Pocket 3 to extend the field of view to 108°.', 375000.0, '{"Brand": "DJI", "Compatibility": "DJI Osmo Pocket 3", "Environmental": "Environmental ProtectionNo", "Item Type": "Lens", "Lens Mount": "Add-on", "Lens Type": "Wide Angle", "Mfr. Model Number": "CP.OS.00000307.01", "Physical": "Dimensions0.92 × 0.7 × 0.3″ Weight0.13 oz", "Zoom Type": "Fixed Focal Length"}', 'Includes

