INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (585, 2, 14, 'DJI Zenmuse DL 75mm f/1.8', 'dji-zenmuse-dl-75mm-f-1-8', 'The DJI Zenmuse DL 75mm f/1.8 is a compact and lightweight lens designed for use with DJI’s Zenmuse X9-8K and X9-8K Air gimbals. Key features include:

55mm filter diameter
Minimal chromatic aberration
