INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (596, 2, 15, 'DZOFilm Catta Ace Full Frame Zoom 2-Lens Kit (EF)', 'dzofilm-catta-ace-full-frame-zoom-2-lens-kit-ef', 'A well-rounded pair of full-frame cine zoom lenses for EF-mount cameras, this DZOFilm Catta Ace Full Frame Zoom 2-Lens Kit bundles two reasonably fast zooms that cover a combined normal-to-telephoto range to meet a wide variety of shooting needs.

The DZOFilm Catta Ace Full Frame Zoom 2-Lens Kit (EF) includes:

