INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (684, 2, 19, 'Fuji GF 250mm f/4 R LM OIS WR', 'fuji-gf-250mm-f-4-r-lm-ois-wr', 'The Fuji GF 250mm f/4 R LM OIS WR is a medium telephoto 197.5mm-equivalent prime for Fuji G-mount cameras. Key features include:

Great for portraiture and landscape photography
Manual aperture and focus rings
Fast, accurate autofocus and built-in image stabilization
