INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (687, 2, 19, 'Fuji GF 32-64mm f/4 R LM WR', 'fuji-gf-32-64mm-f-4-r-lm-wr', 'The Fuji GF 32-64mm f/4 R LM WR is a wide to normal range zoom lens for the Fuji G-mount cameras. Key features include:

Fuji G-mount
