INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (695, 2, 19, 'Fuji GF 80mm f/1.7 R WR', 'fuji-gf-80mm-f-1-7-r-wr', 'The Fuji GF 80mm f/1.7 R WR is a versatile, fast, and compact short portrait-length prime for Fuji G-mount cameras. Key features include:

Great for portraits, weddings, and low-light shooting
Advanced optical design
Fast, accurate, and quiet autofocus
