INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (752, 2, 19, 'Fuji XF 33mm f/1.4 R LM WR', 'fuji-xf-33mm-f-1-4-r-lm-wr', 'The Fuji XF 33mm f/1.4 R LM WR is a fast-aperture normal-length prime designed for Fuji X-mount mirrorless cameras. Key features include:

Normal-length Fuji X-mount APS-C format prime
