INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (759, 2, 19, 'Fuji XF 55-200mm f/3.5-4.8 R LM OIS', 'fuji-xf-55-200mm-f-3-5-4-8-r-lm-ois', 'The Fuji XF 55-200mm f/3.5-4.8 R LM OIS is a telephoto lens designed for Fuji X-mount mirrorless cameras. Key features include:

Great for daytime sports, wildlife, and travel photography
4.5-stop optical image stabilization
