INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (760, 2, 19, 'Fuji XF 56mm f/1.2 R', 'fuji-xf-56mm-f-1-2-r', 'The Fuji XF 56mm f/1.2 R is a fast-aperture portrait lens for Fuji X-mount cameras. Key features include:

