INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (767, 2, 19, 'Fuji XF 8mm f/3.5 R WR', 'fuji-xf-8mm-f-3-5-r-wr', 'The Fuji XF 8mm f/3.5 R WR is a compact, lightweight ultra-wide prime for APS-C format Fuji X cameras. Key features include:

