INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (768, 2, 19, 'Fuji XF 90mm f/2 R LM WR', 'fuji-xf-90mm-f-2-r-lm-wr', 'The Fuji XF 90mm f/2 R LM WR is a high-quality short-tele/portrait lens designed for Fuji X-mount cameras. Key features include:

