INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (774, 2, 20, 'Fujinon 20-120mm T3.5 Cabrio Premier w/ SS-15D Control Kit', 'fujinon-20-120mm-t3-5-cabrio-premier-w-ss-15d-control-kit', 'The Fujinon 20-120mm T3.5 Cabrio Premier w/ SS-15D Control Kit includes:

Fujinon 20-120mm T3.5 Cabrio Premier PL
