INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (779, 2, 19, 'Fujinon Duvo HZK 24-300mm with SS-15D Servo Kit (PL)', 'fujinon-duvo-hzk-24-300mm-with-ss-15d-servo-kit-pl', 'The Fujinon Duvo HZK 24-300mm with SS-15D Servo Kit (PL) includes:

