INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (782, 2, 20, 'Fujinon MK18-55mm T2.9 for Sony E', 'fujinon-mk18-55mm-t2-9-for-sony-e', 'The Fujinon MK18-55mm T2.9 for Sony E is a lightweight cinema zoom for Sony APS-C cameras and Super35 camcorders. Key features include:

Fast T2.9 Aperture
Parfocal with minimum focus breathing
Geared controls for focus, iris and zoom
