INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (791, 2, 20, 'Fujinon UA18X5.5BERD B4 Lens for 2/3 Sensors', 'fujinon-ua18x5-5berd-b4-lens-for-2-3-sensors', 'The Fujinon UA18X5.5BERD B4 Lens for 2/3 Sensors is a 5.5-100mm lens that gives 2/3"-format cameras an ultra-wide to telephoto angle of view. Key features include:

5.5-100mm lens for 2/3" format
