INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (795, 2, 20, 'Fujinon XA20SX8.5BERM-K3 B4 Lens for 2/3 Sensors', 'fujinon-xa20sx8-5berm-k3-b4-lens-for-2-3-sensors', 'The Fujinon XA20SX8.5BERM-K3 is an 8.5-170mm lens that gives B4-mount, 2/3"-format cameras a wide to super-telephoto angle of view with servo control. Key features include:

