INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (826, 2, 24, 'Hasselblad XCD 30mm f/3.5', 'hasselblad-xcd-30mm-f-3-5', 'The Hasselblad XCD 30mm f/3.5 is a wide-angle prime lens for the Hasselblad X1D II 50C and Hasselblad 907X 50C. Key features include:

Great for landscape and architectural photography
Fast, accurate autofocus with full-time manual focusing
