INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (829, 2, 24, 'Hasselblad XCD 38mm f/2.5 V', 'hasselblad-xcd-38mm-f-2-5-v', 'The Hasselblad XCD 38mm f/2.5 V is a versatile wide-angle prime for the Hasselblad X1D and X2D camera systems. Key features include:

Great for landscape, cityscape, and documentary shooting
Fast, accurate autofocus with full-time manual focusing
Optics designed for sharpness and color accuracy
