INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (848, 1, 26, 'Insta360 ONE RS 1" Edition', 'insta360-one-rs-1-edition', 'The Insta360 ONE RS 1" Edition Camera is part of Insta360’s modular action camera system including a 1" wide angle lens mod, and an update to the the Insta360 ONE R line of cameras. Key features include:

Includes 1" wide angle lens mod
19MP stills; up to 5K30 video recording
Waterproof at depths of 16’ or less
1.2 hour battery life

Updated Modular Action System. The Insta360 ONE RS 1" Edition Camera combines the system’s brain, or Core, with one of three interchangeable lenses. When assembled on the battery base and in the mounting bracket, all components of the RS system are waterproof at depths of 16’ or less. Each lens mod supports video capture at 4K and above,

1-Inch Wide Angle Lens. This configuration of the RS includes a 1-inch wide angle lens mod, featuring a larger 1-inch sensor for better low-light performance, support for 5.3K30, 4K60, and 1080p120 shooting, and 19MP jpg or raw stills. The wide angle lens can capture stills with aspect ratios of 3:2 and 16:9.

Core Module. Each configuration of the One RS includes the Core Module, packed with three microphones with noise reduction and a touchscreen display, which can be oriented to support standard recording or selfie recording. Also included with each configuration is the battery base, rated for up to 1.2 hours per charge, and a mounting bracket, which is necessary for any underwater shooting.', 575000.0, '{"Brand": "Insta360", "Camera Type": "360", "Compatible Media": "microSD", "Item Type": "Camera", "Maximum Video Resolution": "5K", "Screen Type": "Touchscreen and Detachable", "Sensor": "1\\"-Type CMOS Sensor", "Sensor Size": "1-Inch", "Stabilization": "Yes", "Video Format": "5472 × 2328p at 24/25/30 fps5312 × 2988p at 24/25/30 fps3840 × 2160p at 24/25/30/60 fps2720 × 1530 at 24/25/30/60 fps1920 × 1080 at 24/25/30/60/120 fps", "Weather Sealing": "Yes", "Wireless Connectivity": "Wi-Fi and Bluetooth"}', 'Includes

	One RS Core module
	1" mod
	Wide angle lens
	Battery base
	Mounting bracket
	3-Prong to 1/4"-20 adapter
	USB-C cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (849, 1, 26, 'Insta360 ONE RS 4K Edition', 'insta360-one-rs-4k-edition', 'The Insta360 ONE RS 4K Edition is part of Insta360’s modular action camera system including a Boost 4K lens, and an update to the the Insta360 ONE R line of cameras. Key features include:

Includes 4K Boost lens
48MP stills; 6K widescreen video w/ HDR support
Waterproof at depths of 16’ or less
1.2 hour battery life

Updated Modular Action System. The Insta360 ONE RS 4K Edition combines the system’s brain, or Core, with one of three interchangeable lenses. When assembled on the battery base and in the mounting bracket, all components of the RS system are waterproof at depths of 16’ or less. Each lens mod supports video capture at 4K and above,

4K Boost Mod. This configuration of the RS includes a 4K Boost mod, which captures 4K60 video, 48MP stills, and 6K widescreen video with in-camera stabilization and front or rear facing recording options. The 1/2" sensor is supported by Active HDR and can shoot 200 fps at 1080p.

Core Module. Each configuration of the One RS includes the Core Module, packed with three microphones with noise reduction and a touchscreen display, which can be oriented to support standard recording or selfie recording. Also included with each configuration is the battery base, rated for up to 1.2 hours per charge, and a mounting bracket, which is necessary for any underwater shooting.', 675000.0, '{"Brand": "Insta360", "Camera Type": "360", "Compatible Media": "microSD", "Item Type": "Camera", "Maximum Video Resolution": "6K", "Screen Type": "Touchscreen and Detachable", "Sensor": "1/2\\"-Type CMOS Sensor", "Sensor Size": "1-Inch", "Stabilization": "Yes", "Video Format": "6016 × 2560 up to 25fps4000 × 3000 up to 30 fps3840 × 2160 up to 60 fps2720 × 1530 up to 100 fps1920 × 1080 up to 200fps", "Weather Sealing": "Yes", "Wireless Connectivity": "Wi-Fi and Bluetooth"}', 'Includes

	One RS Core module
	4K Boost lens
	Battery base
	Mounting bracket
	3-Prong to 1/4"-20 adapter
	USB-C cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (850, 1, 26, 'Insta360 ONE RS Twin Edition', 'insta360-one-rs-twin-edition', 'The Insta360 ONE RS Twin Edition is part of Insta360’s modular action camera system including the 4K Boost and 360 lens mods, and an update to the the Insta360 ONE R line of cameras. Key features include:

Includes 4K Boost and 360 lens mods
Up to 6K widescreen / 5.7K 360° video
Waterproof at depths of 16’ or less
1.2 hour battery life

Updated Modular Action System. The Insta360 ONE RS Twin Edition combines the system’s brain, or Core, with two of the three interchangeable lenses in the ONE RS lineup. When assembled on the battery base and in the mounting bracket, all components of the RS system are waterproof at depths of 16’ or less. Each lens mod supports video capture at 4K and above.

360 Lens Mod. One of the mods included with this configuration is the 360 lens, capable of shooting 5.7K 360° footage. If you use a selfie stick or mount, creative effects can eliminate them from the footage, and you can also reframe a shot after recording to get the perfect angle.

4K Boost Mod. This kit also includes a 4K Boost mod, which captures 4K60 video, 48MP stills, and 6K widescreen video with in-camera stabilization and front or rear facing recording options. The 1/2" sensor is supported by Active HDR and can shoot 200 fps at 1080p.

Core Module. Each configuration of the One RS includes the Core Module, packed with three microphones with noise reduction and a touchscreen display, which can be oriented to support standard recording or selfie recording. Also included with each configuration is the battery base, rated for up to 1.2 hours per charge, and a mounting bracket, which is necessary for any underwater shooting.', 625000.0, '{"Brand": "Insta360", "Camera Type": "360", "Compatible Media": "microSD", "Item Type": "Camera", "Maximum Video Resolution": "6K", "Screen Type": "Touchscreen and Detachable", "Sensor": "1/2\\"-Type CMOS Sensor", "Sensor Size": "1-Inch", "Stabilization": "Yes", "Video Format": "4K Boost Mod6016 × 2560 up to 25fps4000 × 3000 up to 30 fps3840 × 2160 up to 60 fps2720 × 1530 up to 100 fps1920 × 1080 up to 200fps", "Weather Sealing": "Yes", "Wireless Connectivity": "Wi-Fi and Bluetooth"}', 'Includes

	ONE RS Core module
	4K Boost mod
	360 lens mod
	Lens cover
	Mounting bracket
	USB-C cable
	3-prong to 1/4"-20 adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (851, 1, 26, 'Insta360 Pro 2 Spherical VR 360 8K Camera', 'insta360-pro-2-spherical-vr-360-8k-camera', 'The Insta360 Pro 2 Spherical VR 360 8K Camera is a compact, 6-lens device that captures 360°, 3D video & images to 6 microSD cards and 1 SD card while also being able to live stream in 4K to compatible streaming services. Key features include:

Records 360° 3D video at up to 8K resolution
Six 200° cameras stitched and stabilized in real time
Live stream 360° 3D 4K video to compatible platforms while recording
Requires 6 microSD cards and 1 SD card rated V30 or higher (not included!)

What’s New? The Insta360 Pro 2 camera is a substantial upgrade to the Insta360 Pro and corrects many of our complaints with the original. First thing you’ll likely notice are new antennae top-mounted on the camera. They correspond with a now-integrated GPS unit and extended wireless control system that works up to 1000 ft away. Single SD card recording has been expanded to six microSD cards and one SD card to increase video recording to 120 Mbps and 3 times as fast as the original. The camera can now record full 360, 3D footage internally at 8K. A top 1/4" threaded hole and 1/8" audio in make capturing external audio much easier, and and HDR mode helps out in uneven lighting.

360 Degree 3D Video Recording. The Insta360 Pro 2 Spherical VR 360 8K Camera is a compact, 6 lens device that captures 360 degree 3D video at up to 8K 30fps. Non-3D 360° footage can be recorded at up to 8K 60fps. The primary drawback with all-in-one 360° camera systems is resolution, but at 4 times the resolution of lower end 4K cameras, this system provides a much sharper image when played in 360° viewers and headsets.

Live Stream 360° 3D 4K Video. The camera is capable of livestreaming 4K 360 video to compatible streaming services like YouTube and Facebook Live. The feature allows you to locally stream a live preview to compatible VR headsets. The Insta360 can be connected to the internet via wi-fi or ethernet, but ethernet is always advised for bitrates required to stream 4K video. Setup is kept simple with well designed Mac, PC, Android, and iOS applications.

Records To microSD & SD Memory. All video and photos can be stored onto common microSD and SD memory cards featuring a V30 rating or higher. Multiple formatting option are available for photos and video from pre-stitched JPG and MP4 files to RAW photos and untouched video captures from each of the 6 lenses. Looking for a one-click media solution? We also rent a 128GB Media Bundle that includes all the cards you need to get started plus a seven port USB hub for simple file management.

Live Stitching, Image Stabilization, & On-Board Mics. The unit’s internal processor is capable of real-time video stitching of 4K video, and the Insta 360 II has improved image stabilization. Audio is recorded with four on-board microphones capable of producing ambisonics audio. With so much packed into one small sphere, the fans work hard to keep everything cool. Fan noise can become audible in warm shooting locations, so we recommend capturing critical audio externally or using the 1/8" input jack to get your mic further away from fan noise.

50 Minute Battery Life. The camera can be powered for up to 50 minutes with its swappable Insta360 PT854291-2S Pro Battery Pack. If power runs low and you need to keep shooting, the included AC adapter can power and charge the internal battery simultaneously. We also rent a Dual Charging Station to charge spare batteries apart from the camera.

Also Available in a Kit. If you’re looking for an all-in-one solution, please check out our Insta360 Pro 2 VR 360 8K Camera Premium Kit. It includes everything you’ll need from batteries to cards and even a tripod.', 7475000.0, '{"Brand": "Insta360", "Camera Type": "360", "Compatible Media": "microSD", "Item Type": "Camera", "Lens": "Maximum Aperture: f/2.4 and Angle of View: 200° (per lens)", "Maximum Video Resolution": "8K", "Resolutions": "360 Photos: Maximum at 12,000 × 12,000 (RAW, JPEG)\\n\\nReal-time 3D 360 Videos: Maximum at 3840 × 3840 at 120 fps (MP4 via H.264) (4K)\\n\\nPost-Stitched 3D 360 Videos: maximum at 7680 × 7680 at 30 fps (MP4 via H.265) (8K)\\n\\nPost-Stitched 360 Videos: maximum at 7680 × 7680 at 60 fps (MP4 via H.265) (8K)", "Sensor Size": "1-Inch", "Stabilization": "Yes", "Weather Sealing": "No", "Wireless Connectivity": "Wi-Fi"}', 'Includes

	Insta360 Pro 2 camera
	Insta360 Pro battery
	Camera AC adapter
	Lens cover
	USB ethernet adapter
	3ft ethernet cable
	FarSight Transmitter
	FarSight Receiver
	FarSight AC adapter (2x)
	FarSight Transmitter clamp
	Male antenna
	Female antenna (5x)
	USB micro to lightning cable
	USB micro to USB micro cable
	USB micro to Type C cable

Memory cards not included', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (852, 1, 26, 'Insta360 X3', 'insta360-x3', 'The Insta360 X3 gives you high-definition 360° video in a pocket-sized camera. Key features include:

Dual-Mode 360 & Standard Pocket Camera
6-Axis Gyroscope
4K Single-Lens Standard Camera Mode
Bluetooth 5.0 Support, iOS/Android App

360° video On The Go. With an upgraded 1/2" sensor and larger touchscreen, the Insta360 X3 360° Camera is capable of capturing high definition 360° and single-lens video with one portable action camera. The X3 offers an action-ready design with AI-powered software for an intuitive approach to creating dynamic content in any environment. Its rugged IPX8 design is natively waterproof up to 33’ and has a built-in rechargeable 1800mAh battery for increased shooting time.

5.7K 360° Video, 4K Single-Lens Mode. Dual 360° lenses on the X3 can capture up to 5.7K video and 72MP photos with ease. You can switch to single-lens shooting and record 4K video at up to 30 fps. For extremely wide-angle 170° shots, turn on MaxView mode with 2.7K resolution.

Ultrasmooth, Stabilized Footage. The X3 ensures your footage remains stabilized thanks to its 6-axis gyroscope and FlowState Stabilization technology. 360° active HDR mode is specifically designed for action sports like ziplining and mountain biking by keeping your video stable as you move while maintaining details in the highlights and shadows for more vibrant footage. Horizon lock keeps the horizontal plane of your video consistent and allows the camera to rotate freely while keeping the sky-line level.

What About Memory? The X3 does not record internally and accepts microSD cards, but we do not include one with this rental. Feel free to check out the Recommended section on your screen to find a memory card that works for you!', 1050000.0, '{"360 Stitched Video Formats": "5760 × 2880 at 24, 25, 30 fps4096 × 2160 at 30, 60 fps", "Battery Life": "1.4 Hours per Charge", "Brand": "Insta360", "Camera Type": "360", "Charging Method": "USB", "Compatible Media": "microSD", "Focal Length": "6.7mm (35mm Equivalent Focal Length: 6.7mm)", "Item Type": "Camera", "Maximum Video Resolution": "5K", "Memory Card Slot": "microSD", "Screen Type": "Touchscreen and Fixed", "Sensor Size": "1-Inch", "Stabilization": "Yes", "Stitching Resolution": "5.7K (Video)", "Video Format": "4096 × 2160 at 24/25/30 fps (MP4)3592 × 1320 at 24/25/30/50/60 fps (MP4)2704 × 1520 at 24/25/30/50/60 fps (MP4)1920 × 1080p at 24/25/30/50/60 fps (MP4)", "Waterproof Depth Rating": "33.0’", "Weather Sealing": "Yes", "Wi-Fi": "Yes", "Wireless Connectivity": "Wi-Fi and Bluetooth"}', 'Includes

	Insta360 X3 360 Camera
	Insta360 X3 Battery
	Insta360 X3 Lens Protector
	USB 2.0 A Male to Type C
	Bag – Porta Brace PB-B6 Stuff Sack', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (853, 1, 26, 'Insta360 X3 Premium VR Kit', 'insta360-x3-premium-vr-kit', 'The Insta360 X3 Premium VR Kit features a full kit dedicated to enhance your high-definition filming experience. This kit provides you with all the tools needed for your production, including a full 360° camera with a utility frame, a microphone adapter for audio recording, a quick reader that allows you to directly record to the module and transfer to your Apple or Android device, and much more. Click on any of the highlighted links below for more information.

The Insta360 X3 Premium VR Kit includes:

Insta360 X3
