INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (952, 2, 31, 'Lensbaby Double Glass II Optic', 'lensbaby-double-glass-ii-optic', 'The Lensbaby Double Glass II Optic is a 50mm optic lens designed to create the perfect “sweet spot” of focus surrounded by an artistic blend of blur and bokeh. Key features include:

For full-frame cameras
f/2.5 to f/22 aperture
12-blade diaphragm
Manual focus

Focus Fronted. The Lensbaby Double Glass II Optic offers an aperture of f/2.5 to f/22, helping to create a focus point in your image surrounded by a perfectly blended blur. The aperture adjustment is located on the front of the optic, and is used to change the diameter of the “sweet spot”. This optic lens is also compatible with all current Optic Swap lens bodies and macro accessories.', 475000.0, '{"Angle of View": "45º", "Aperture Blades": "12", "Brand": "Lensbaby", "Dimensions": "3 × 3″ (ø x L)", "Filter Size": "46.0mm", "Filter Type": "Screw-On", "Focal Length": "50-50", "Focus Type": "Manual Focus Only", "Groups/Elements": "1/2", "Item Type": "Lens", "Lens Format": "Full-Frame", "Lens Mount": "Add-on", "Lens Type": "Standard and Specialty", "Maximum Aperture": "2.5", "Mfr. Model Number": "LBDGIIO", "Minimum Focusing Distance": "1.25’", "Stabilization": "No", "Weather Sealing": "No", "Weight": "0.3 lb.", "Zoom Type": "Fixed Focal Length"}', 'Includes

	Lensbaby Double Glass II Optic
	Swap tool', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (953, 2, 31, 'Lensbaby Edge 50 Optic', 'lensbaby-edge-50-optic', 'The Edge 50 Optic is a specialty optic unit designed to work with any of Lensbaby’s Optic Swap lens bodies (see Recommended on the left-hand side of this page). Key features include:

50mm flat-field focus optic
f/3.2 maximum aperture
Eight elements in six groups
Optic unit only; Optic Swap lens body required

Add-On For Existing Users. This is just the Edge 50 Optic. We’re renting it separately for existing Lensbaby Composer Pro owners and people who rent our other Lensbaby Composer Pro units.

50mm Flat-Field Focus Optic. This normal-range optic uses a flat field of focus to create a focus line/slice across the frame that’s selected by tilting the Composer Pro II’s ball-and-socket joint. You can also control the “slice of focus” size by adjusting aperture, allowing simple false-miniature images. The Composer Pro II is compatible with both Canon crop-frame and full-frame cameras.

f/3.2 Maximum Aperture. The f/3.2 aperture isn’t ideal for handheld low-light shooting, but that’s not what this lens is intended for. The six-group/eight multi-coated element optical formula produces surprisingly good image quality for a Lensbaby and provides a much more cost-friendly option than a tilt-shift lens. Its nine-blade internal aperture enables circular out-of-focus highlights.', 425000.0, '{"Brand": "Lensbaby", "Focus Type": "Manual Focus Only", "Item Type": "Lens", "Lens Format": "Full-Frame", "Lens Mount": "Add-on", "Lens Type": "Standard and Specialty", "Maximum Aperture": "3.2", "Mfr. Model Number": "LBE50", "Stabilization": "No", "Weight": "0.3 lb.", "Zoom Type": "Fixed Focal Length"}', 'Includes

	Edge 50 optic
	Front caps
	Lens pouch', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (954, 2, 31, 'Lensbaby Edge 80 Optic', 'lensbaby-edge-80-optic', 'The Edge 80 Optic is a specialty optic unit designed to work with any of Lensbaby’s Optic Swap lens bodies (see Recommended on the left-hand side of this page). Key features include:

80mm flat-field focus optic
f/2.8 maximum aperture
Five elements in four groups
Optic unit only; Optic Swap lens body required

Optic Unit Only. This is just the Edge 80 Optic. We’re renting it separately to give users the flexibility to choose which lens body and optic is right for them.  See Recommended on the left-hand side of this page for compatible lens bodies in various mounts.

80mm Flat-Field Focus Optic. This normal-/short-tele focal range optic uses a flat field of focus to create a focus line/slice across the frame that’s selected by tilting the Composer Pro’s ball-and-socket joint. You can also control the “slice of focus” size by adjusting aperture, allowing simple false-miniature images.

f/2.8 Maximum Aperture. The fast f/2.8 aperture enables decent low-light performance. The four-group/five multi-coated element optical formula produces surprisingly good image quality for a Lensbaby and provides a much more cost-friendly option than a tilt-shift lens. The twelve-blade internal aperture produces a circular bokeh at all stops that you can’t get out of many substantially more expensive pro lenses.', 475000.0, '{"Brand": "Lensbaby", "Item Type": "Lens", "Lens Mount": "Add-on", "Lens Type": "Telephoto and Specialty", "Maximum Aperture": "2.8", "Mfr. Model Number": "LBE80", "Stabilization": "No", "Zoom Type": "Fixed Focal Length"}', 'Includes

	Edge 80 optic
	Front & rear caps
	Lens pouch', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (955, 2, 31, 'Lensbaby Sol 45mm f/3.5 for Canon EF', 'lensbaby-sol-45mm-f-3-5-for-canon-ef', 'The Lensbaby Sol 45mm f/3.5 for Canon EF is a fully manual selective-focus specialty lens designed for Canon EF-mount cameras. Key features include:

Unique selective-focus specialty lens
Center-locking focus
Dual bokeh blades for creative effects
Canon EF-mount lens

Unique Selective-Focus Prime. The Lensbaby Sol 45mm f/3.5 is a unique prime that gives you extensive control over bokeh and selective focusing. It lets you produce an ultra-sharp circular area of focus surrounded by blur and smooth bokeh. You can isolate your subject within the frame by tilting the lens.

Center-Locking Focus. The Sol 45’s center-locking feature facilitates fast and easy focusing by letting you twist the lens into the lock position when your subject is in the center of the frame.

Dual Bokeh Blades. If you’re looking to add even more creative effects to your photos, you’re in luck. The Sol 45mm has two bokeh blades—each on its own hinged arm at the edge of the lens—which you can use to add subtle lines and textures to bokeh. Just bring the blades into the lens’s field of view and then rotate them horizontally, vertically, or diagonally to find the effect that suits you.', 450000.0, '{"Aperture Blades": "2", "Brand": "Lensbaby", "Groups/Elements": "2/3", "Hood Included": "No", "Item Type": "Lens", "Lens Mount": "Canon EF", "Lens Type": "Wide Angle and Specialty", "Macro Reproduction Ratio": "1:6", "Mfr. Model Number": "LBS45C", "Tilt/Shift": "+/- 8.5° Tilt"}', 'Includes

	Lensbaby Sol 45mm f/3.5
	Front & rear caps', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
