INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1008, 2, 36, 'Mitakon SpeedMaster 35mm T1.0 for Fuji X', 'mitakon-speedmaster-35mm-t1-0-for-fuji-x', 'The Mitakon Zhongyi SpeedMaster 35mm T1 for Fuji X is a fully manual, fast-aperture cine prime designed for Fuji X-mount cameras. Key features include:

Great in low light and for subject/background isolation
High-quality optics for sharpness and color accuracy
