INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1011, 2, 36, 'Mitakon SpeedMaster 35mm f/0.95 Mark II for Fuji X', 'mitakon-speedmaster-35mm-f-0-95-mark-ii-for-fuji-x', 'The Mitakon Zhongyi SpeedMaster 35mm f/0.95 Mark II for Fuji X is a fully manual, fast-aperture prime lens designed for Fuji X-mount cameras. Key features include:

