INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1085, 2, 38, 'Nikon Z 17-28mm f/2.8', 'nikon-z-17-28mm-f-2-8', 'The Nikon Z 17-28mm f/2.8 is a compact, fast-aperture, ultra-wide zoom for Nikon Z-Mount cameras. Key features include:

