INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1325, 1, 47, 'RED V-RAPTOR XE 8K VV (Canon RF)', 'red-v-raptor-xe-8k-vv-canon-rf', 'The V-RAPTOR XE 8K VV Camera from RED DIGITAL CINEMA delivers the 8K global shutter and compact design of the V-RAPTOR X, while focusing on the core features essential to modern filmmaking. Built on RED’s DSMC3 platform, the XE provides a large-format VV sensor in a lightweight 4 lb body, capturing 8K video in up to 60 fps with 17+ stops of dynamic range. Balancing high-end performance with class-leading value, the XE omits advanced Global Vision features like Phantom Track and Extended Highlights, but retains the same image quality, workflow flexibility, and robust connectivity that define RED’s V-RAPTOR line.

Key features include:

Global Shutter Full-Frame VV Sensor
	Lightweight & Compact DSMC3 Design
	Locking Canon RF Lens Mount
	Netflix approved camera', 20450000.0, '{"Brand": "RED", "Camera Mount": "Canon RF", "Camera Type": "Cinema", "Compatible Media": "CFexpress Type B", "Item Type": "Camera", "Maximum Video Resolution": "8K", "Sensor Size": "VistaVision", "Stabilization": "No", "Weather Sealing": "No", "Wireless Connectivity": "Wi-Fi"}', 'Includes

	RED V-RAPTOR XE 8K VV (Canon RF)', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
