INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1405, 2, 49, 'Rokinon AF 35mm f/2.8 FE for Sony E', 'rokinon-af-35mm-f-2-8-fe-for-sony-e', 'The Rokinon AF 35mm f/2.8 FE for Sony E is a wide-angle lens that offers full-frame support for Sony E-Mount cameras and camcorders. Key features include:

Full- and crop-frame compatible
Advanced optics for high-quality images
Fast, accurate autofocus with manual-focus override
