INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1406, 2, 49, 'Rokinon AF 50mm f/1.4 II for Sony E', 'rokinon-af-50mm-f-1-4-ii-for-sony-e', 'The Rokinon AF 50mm f/1.4 II for Sony E is a fast normal-length prime for Sony E-mount cameras. Key features include:

