INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1407, 2, 49, 'Rokinon AF 75mm f/1.8 FE Lens for Sony E', 'rokinon-af-75mm-f-1-8-fe-lens-for-sony-e', 'The Rokinon AF 75mm f/1.8 FE for Sony E is a short-telephoto prime that’s excellent for portraiture. Key features include:

Great for portraiture and low-light shooting
High-quality optics for sharpness and color fidelity
Fast, quiet, accurate autofocus; full-time manual override
