INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1412, 2, 49, 'Rokinon SP 10mm f/3.5 for Canon EF', 'rokinon-sp-10mm-f-3-5-for-canon-ef', 'The Rokinon SP 10mm f/3.5 for Canon EF is a super wide-angle prime that offers full-frame coverage for Canon EF-mount cameras and camcorders. Key features include:

