INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1463, 2, 50, 'Schneider Cine-Xenar III 18mm T2.2 EF', 'schneider-cine-xenar-iii-18mm-t2-2-ef', 'The Schneider Cine-Xenar III 18mm T2.2 EF is a high-quality Canon EF-mount cinema lens for use with Super35 sensor cameras. Key features include:

27mm-equivalent focal length after sensor-crop factor
Telecentric optical design for digital sensors
Extremely smooth and round bokeh
104mm outside diameter, 100mm x 0.75 filter thread

Super35 Coverage. The Schneider Cine-Xenar III 18mm T2.2 easily covers a Super35 film frame with 31.5mm image circle, providing support up to 2K/4K/5K Cinema.

Wide Angle. This lens provides a focal length equivalent to about 27mm after sensor-crop factor.

Cinema Lens Build. Across the board, the Cine-Xenar III lineup has an outside diameter of 104mm with a 100mm x 0.75 filter thread, and they’re all color-matched to allow simple lens changes. There’s virtually no breathing/change in image size when focusing and all focus and iris gears are in the same position.

High-Quality Optics. The telecentric optical design provides even sensor illumination, and the special Schneider-Kreuznach high-performance coating improves image performance and flare suppression. The eighteen-blade iris provides extremely smooth and round bokeh for exceptional backgrounds.', 4125000.0, '{"Angle of View": "63.2º", "Aperture Blades": "18", "Brand": "Schneider", "Dimensions": "4.1 × 7.1″ (ø x L)", "Filter Size": "100.0mm", "Filter Type": "Screw-On and Matte Box Mount", "Focal Length": "18-18", "Focus Rotation": "270º", "Focus Type": "Manual Focus Only", "Front Lens Diameter": "104mm", "Gearing": "0.8 MOD focus, iris", "Item Type": "Lens", "Lens Format": "Super35 and APS-C", "Lens Mount": "Canon EF", "Lens Type": "Wide Angle, Cine, and For DSLR", "Maximum Aperture": "2.2", "Mfr. Model Number": "1072700", "Minimum Focusing Distance": "11\\"", "Stabilization": "No", "Weather Sealing": "No", "Weight": "4.5 lb.", "Zoom Type": "Fixed Focal Length"}', 'Includes

	Schneider Cine-Xenar III 18mm T2.2 EF
	Front & rear caps
	Case', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1464, 2, 50, 'Schneider Cine-Xenar III 18mm T2.2 PL', 'schneider-cine-xenar-iii-18mm-t2-2-pl', 'The Schneider Cine-Xenar III 18mm T2.2 PL is a high-quality PL-mount cinema lens for use with Super35 sensor cameras. Key features include:

