INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1570, 2, 51, 'Sigma 23mm f/1.4 DC DN Contemporary for Fuji X', 'sigma-23mm-f-1-4-dc-dn-contemporary-for-fuji-x', 'The Sigma 23mm f/1.4 DC DN Contemporary for Fuji X is a compact, fast-aperture, wide-angle prime with high-quality optics. This version is for Fuji X-mount mirrorless cameras. Key features include:

