INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1647, 2, 51, 'Sigma 50mm f/2 DG C for L-Mount', 'sigma-50mm-f-2-dg-c-for-l-mount', 'The Sigma 50mm f/2 DG C is a portrait-length prime for full-frame L-mount cameras and an update to the Sigma 50mm f/2 DG DN Contemporary. Key features include:

Very portable at 2.8 × 2.7″
Stepping AF motor
Part of Sigma’s I Series
Knurled aperture & focus rings

Sigma I Series. The Sigma 50mm f/2 DG C belong’s to Sigma’s 1 Series group of lenses, which is a collection that prioritizes compactness without sacrificing performance. These lenses offer all-metal construction with precision-cut aluminum, an elegant finish, and pleasingly tactile knurled focus and aperture rings.

Stepping Motor. Equipped with a stepping AF motor, this lens has admirable autofocus speeds for videography. This is complemented by a manual aperture ring and an AF/MF toggle with a raised arc shape for fast switching. Please note that the aperture ring is not de-clickable and has 1/3-stop clicks.

Classic Portrait Prime. This all-purpose lens is sharp, compact, and fast. With its classic “normal” focal length, it is ideal for accurately capturing the world around you, whether it’s for journalism, street photography, or portraiture.

Try it with These L-Mount Cameras. The portable nature of this lens makes it a great option for shooters on the go and pairs well with slightly more compact cameras like the Panasonic Lumix S9, the Sigma BF, and the Sigma fp L. However, it’ll work with any L-mount system.', 1275000.0, '{"Angle of View": "46.8°", "Aperture Blades": "9, rounded", "Brand": "Sigma", "Dimensions": "2.8 × 2.7″ (ø x L)", "Filter Size": "58.0mm", "Filter Type": "Screw-On", "Focal Length": "50-50", "Focus Type": "Autofocus", "Groups/Elements": "9/11", "Item Type": "Lens", "Lens Format": "Full-Frame", "Lens Mount": "L", "Lens Type": "Standard and For Mirrorless", "Maximum Aperture": "2.0", "Mfr. Model Number": "31B969", "Minimum Focusing Distance": "1.5’", "Stabilization": "No", "Weather Sealing": "Yes", "Weight": "0.76 lb.", "Zoom Type": "Fixed Focal Length"}', 'Includes

	Sigma 50mm f/2 DG C for L-Mount
	58mm protective filter
	Hood
	Lens bag', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1648, 2, 51, 'Sigma 50mm f/2 DG C for Sony E', 'sigma-50mm-f-2-dg-c-for-sony-e', 'The Sigma 50mm f/2 DG C is a portrait-length prime for full-frame E-mount cameras and an update to the Sigma 50mm f/2 DG DN Contemporary. Key features include:

Very portable at 2.8 × 2.8″
Stepping AF motor
Part of Sigma’s I Series
Knurled aperture & focus rings

Sigma I Series. The Sigma 50mm f/2 DG C belong’s to Sigma’s 1 Series group of lenses, which is a collection that prioritizes compactness without sacrificing performance. These lenses offer all-metal construction with precision-cut aluminum, an elegant finish, and pleasingly tactile knurled focus and aperture rings.

Stepping Motor. Equipped with a stepping AF motor, this lens has admirable autofocus speeds for videography. This is complemented by a manual aperture ring and an AF/MF toggle with a raised arc shape for fast switching. Please note that the aperture ring is not de-clickable and has 1/3-stop clicks.

Classic Portrait Prime. This all-purpose lens is sharp, compact, and fast. With its classic “normal” focal length, it is ideal for accurately capturing the world around you, whether it’s for journalism, street photography, or portraiture.

Try it with These E-Mount Cameras. The portable nature of this lens makes it a great option for shooters on the go and pairs well with slightly more compact cameras like the Sony ZV-E1 or the Sony Alpha a7C II. However, it’ll work with any E-mount system, including APS-C sensor cameras like the Sony a6600, where it will provide an equivalent focal length of 75mm. To maintain the 50mm apparent length on a crop sensor camera, consider the Sigma 35mm f/2 DG C, which has an equivalent focal length of 52mm.', 1275000.0, '{"Angle of View": "46.8°", "Aperture Blades": "9, rounded", "Brand": "Sigma", "Dimensions": "2.8 × 2.8″ (ø x L)", "Filter Size": "58.0mm", "Filter Type": "Screw-On", "Focal Length": "50-50", "Focus Type": "Autofocus", "Groups/Elements": "9/11", "Item Type": "Lens", "Lens Format": "Full-Frame", "Lens Mount": "Sony E", "Lens Type": "Standard and For Mirrorless", "Maximum Aperture": "2.0", "Mfr. Model Number": "31B965", "Minimum Focusing Distance": "1.5’", "Stabilization": "No", "Weather Sealing": "Yes", "Weight": "0.76 lb.", "Zoom Type": "Fixed Focal Length"}', 'Includes

	Sigma 50mm f/2 DG C for Sony E
	58mm protective filter
	Hood
	Lens bag', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1649, 2, 51, 'Sigma 50mm f/2 DG DN Contemporary for L-Mount', 'sigma-50mm-f-2-dg-dn-contemporary-for-l-mount', 'The Sigma 50mm f/2 DG DN Contemporary for L-Mount is a compact, fast-aperture normal-length prime with high-quality optics. An updated version of this lens is available here. Key features include:

Fast-aperture normal-length prime
Advanced optics; compact, lightweight build
Fast, smooth, and quiet autofocus with manual override
Sigma UD-11 USB dock compatible

Fast-Aperture Standard Prime. The Sigma 50mm f/2 DG DN Contemporary’s build is compact and ultra-light. It weighs just under 0.8 lb. and takes 58mm filters. Its focal length, fast f/2 maximum aperture, and rounded nine-blade diaphragm make it great for portraiture, street photography, general-purpose photography, and much more. Using an APS-C camera? You’ll get a 75mm equivalent focal length.

High-Quality Optical Design. As a part of Sigma’s Contemporary lens line, the 50mm f/2 goes through rigorous testing to ensure high image quality. Its nine-group/eleven-element optical design features one Special Low-Dispersion element and three aspherical elements that correct for chromatic aberrations and color fringing while ensuring high image sharpness, clarity, and contrast. A Super Multi-Layer coating minimizes lens flare and ghosting, helping to provide high contrast even in strong lighting.

Fast, Quiet Autofocus System. The 50mm’s integrated stepping autofocus motor provides fast, quiet operation in a broad range of shooting situations, and its optimized AF algorithm helps facilitate smooth performance. An aperture ring, an arc-type AF/MF focus-mode switch, and a knurled manual focusing ring make focusing a tactile experience. The 17.7-inch minimum focusing distance and 1:6.9 maximum magnification ratio let you get in pretty close.

Dock Compatible. This lens is compatible with the Sigma UD-11 USB Dock for L-Mount Lenses (separate rental item), allowing you to adjust the focus limiter, autofocus speed, microfocus, and OS settings through the Sigma Optimization Pro software.', 1000000.0, '{"Angle of View": "46.8°", "Brand": "Sigma", "Hood Included": "Yes", "Item Type": "Lens", "Lens Mount": "L", "Lens Type": "Standard", "Macro Reproduction Ratio": "1:6.9", "Mfr. Model Number": "314969", "Minimum Focusing Distance": "1.5’", "Optical Design": "Groups/Elements9/11Special Low-Dispersion Elements1Aspherical Elements3Diaphragm Blades9, Rounded", "Physical": "Dimensions (ø x L) – lens only2.8 × 2.8″Weight – lens only0.8 lb."}', 'Includes

	Sigma 50mm f/2
	Sigma LH633-01 hood
	Sigma LCF-58 III front cap
	Sigma LCR II rear cap
	58mm protective filter
	Bag', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
