INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1708, 2, 51, 'Sigma Cine 14mm T3.2 FF Classic Art Prime (PL)', 'sigma-cine-14mm-t3-2-ff-classic-art-prime-pl', 'The Sigma Cine 14mm T3.2 FF Classic Art Prime (PL) is a professional, compact lens designed for PL-mount cameras and camcorders that produces high-quality images with a unique cinematic look. Key features include:

