INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1733, 2, 51, 'Sigma Cine 35mm T2.5 FF Classic Art Prime (PL)', 'sigma-cine-35mm-t2-5-ff-classic-art-prime-pl', 'The Sigma Cine 35mm T2.5 FF Classic Art Prime (PL) is a professional, compact lens designed for PL-mount cameras and camcorders that produces high-quality images with a unique cinematic look. Key features include:

Depth-of-field control and great low-light capability
Advanced optical design for high-quality images
Standardized focus and iris gear ring positions
