INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1753, 2, 51, 'Sigma Cine 85mm T1.5 FF Prime with /i Technology (PL)', 'sigma-cine-85mm-t1-5-ff-prime-with-i-technology-pl', 'The Sigma Cine 85mm T1.5 FF Prime with /i Technology is a pro-grade, fast-aperture cine lens for PL-mount cameras and camcorders, and an enhanced version of the Sigma Cine 85mm T1.5 FF Prime. Key features include:

