INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1769, 2, 52, 'Sirui 100mm T2.9 Anamorphic 1.6x Full Frame (Canon RF)', 'sirui-100mm-t2-9-anamorphic-1-6x-full-frame-canon-rf', 'The Sirui 100mm T2.9 Anamorphic 1.6x Full Frame (Canon RF) is a portable and durable lens that offers a wide field of view to help you capture theater-screen filling, artistic, cinematic shots with full-frame Canon RF-mount cameras. Key features include:

Enlarges your horizontal field of view up to 60%
1.6x anamorphic squeeze; 2.4:1 & 2.8:1 de-squeezed images
“Sci-Fi Horizontal Flares” and oval bokeh effect
