INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1782, 2, 52, 'Sirui 35mm f/1.8 Anamorphic 1.33x (MFT)', 'sirui-35mm-f-1-8-anamorphic-1-33x-mft', 'The Sirui 35mm f/1.8 Anamorphic 1.33x is a portable and durable lens that offers a wide field of view to help you capture cinematic shots with Micro 4/3 cameras. Key features include:

