INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2007, 2, 55, 'Tamron 35-150mm f/2-2.8 Di III VXD for Nikon Z', 'tamron-35-150mm-f-2-2-8-di-iii-vxd-for-nikon-z', 'The Tamron 35-150mm f/2-2.8 Di III VXD for Nikon Z is an advanced, flexible all-in-one zoom designed for full-frame Nikon Z-mount cameras. Key features include:

