INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2009, 2, 55, 'Tamron 35mm f/1.4 SP Di USD for Canon EF', 'tamron-35mm-f-1-4-sp-di-usd-for-canon-ef', 'The Tamron 35mm f/1.4 SP Di USD for Canon EF is a versatile, high-quality, semi-wide angle prime for Canon EF-mount cameras. Key features include:

Great for landscape, street, and general photography
Excellent low-light performance and depth-of-field control
Fast, quiet, accurate autofocus with full-time manual focus
