INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2024, 2, 12, 'Telephoto Sports Package for Canon', 'telephoto-sports-package-for-canon', 'The Telephoto Sports Package for Canon is a lightweight setup for shooting indoor and outdoor sports. This rental doesn’t include a camera body.

