INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2095, 2, 58, 'Vazen 28mm T2.2 1.8x Anamorphic (RF)', 'vazen-28mm-t2-2-1-8x-anamorphic-rf', 'The Vazen 28mm T2.2 1.8x Anamorphic is a relatively portable Canon RF-mount lens that adds enhanced anamorphic flares and a distinctive cinematic look to your shots. Key features include:

