INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2096, 2, 58, 'Vazen 40mm T2 1.8x Anamorphic (MFT)', 'vazen-40mm-t2-1-8x-anamorphic-mft', 'The Vazen 40mm T2 1.8x Anamorphic is a relatively portable Micro 4/3 lens that adds enhanced anamorphic flares and a distinctive cinematic look to your shots. Key features include:

Cinematic 2.39:1 aspect ratio; 1.8 anamorphic squeeze
Enhanced blue flares and bokeh with minimal breathing
