INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2141, 2, 59, 'Venus Optics Laowa 12mm f/2.8 Zero-D for Canon', 'venus-optics-laowa-12mm-f-2-8-zero-d-for-canon', 'The Venus Optics Laowa 12mm f/2.8 Zero-D for Canon is an ultra-wide angle prime lens for Canon EF-mount and APS-C cameras. Key features include:

