INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2145, 2, 59, 'Venus Optics Laowa 15mm f/2 FE Zero-D (E)', 'venus-optics-laowa-15mm-f-2-fe-zero-d-e', 'The Venus Optics Laowa 15mm f/2 FE Zero-D is an ultra-wide, fast-aperture prime lens for Sony E-mount and APS-C cameras. Key features include:

Great for astrophotography and landscape photography
Great for low-light shooting
Advanced optical design; next to no distortion
Accurate, fully manual focusing

