INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2196, 2, 59, 'Venus Optics Laowa 24mm T8 Pro2be Probe 3-Lens Set (PL)', 'venus-optics-laowa-24mm-t8-pro2be-probe-3-lens-set-pl', 'The Venus Optics Laowa 24mm T8 Pro2be Probe 3-Lens Set (PL) is a kit of three probe lenses designed for macro shooting on up to full-frame PL-mount cameras. Each lens  Key features include:

Includes 35°, 90° periscope, and straight probe lenses
