INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2255, 2, 59, 'Venus Optics Laowa Ranger 16-30mm T2.9 FF Cine Zoom (L)', 'venus-optics-laowa-ranger-16-30mm-t2-9-ff-cine-zoom-l', 'The Venus Optics Laowa Ranger 16-30mm T2.9 FF Cine Zoom (L) is a versatile, full-frame zoom lens designed for use with L-mount cameras. Key features include:

