INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2298, 2, 63, 'Voigtlander 28mm f/2.0 APO-Lanthar Aspherical for Leica M', 'voigtlander-28mm-f-2-0-apo-lanthar-aspherical-for-leica-m', 'The Voigtlander 28mm f/2.0 APO-Lanthar Aspherical is a low-aberration, ultra-sharp, and color-accurate prime lens for Leica M mount cameras. Key features include:

