INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2299, 2, 63, 'Voigtlander 29mm f/0.8 Super Nokton for Micro 4/3', 'voigtlander-29mm-f-0-8-super-nokton-for-micro-4-3', 'The Voigtlander 29mm f/0.8 Super Nokton for Micro 4/3 is an ultra-fast, normal-length prime for Micro 4/3 cameras and camcorders. Key features include:

