INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2445, 2, 66, 'Zeiss Lightweight Zoom LWZ.3 21-100mm T2.9-3.9 (E)', 'zeiss-lightweight-zoom-lwz-3-21-100mm-t2-9-3-9-e', 'The Zeiss Lightweight Zoom LWZ.3 21-100mm T2.9-3.9 (E) is a high-quality cinema zoom designed for E-mount cinema cameras. Key features include:

E mount
31.5-150mm equivalent focal length
