INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2523, 2, 66, 'Zeiss ZE 28mm f/1.4 Otus APO Distagon for Canon', 'zeiss-ze-28mm-f-1-4-otus-apo-distagon-for-canon', 'The Zeiss ZE 28mm f/1.4 Otus APO Distagon is a premium fast-aperture, wide-angle, manual-focus prime lens designed for high-resolution Canon DSLRs. Key features include:

Advanced optical design for high-quality images
Excellent low-light performance; shallow depth of field
