INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2525, 2, 66, 'Zeiss ZE 85mm f/1.4 Otus APO Planar for Canon', 'zeiss-ze-85mm-f-1-4-otus-apo-planar-for-canon', 'The Zeiss ZE 85mm f/1.4 Otus APO Planar for Canon is a premium, fast-aperture, manual-focus prime lens designed for high-resolution Canon EF DSLRs. Key features include:

