INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2527, 2, 66, 'Zeiss ZM 21mm f/2.8 Biogon', 'zeiss-zm-21mm-f-2-8-biogon', 'The Zeiss ZM 21mm f/2.8 Biogon for Leica is a very wide-angle lens with a reasonably fast aperture. Key features include:

